import sys,os
OUTDP3=sys.argv[1]; HERE=os.path.dirname(os.path.abspath(sys.argv[0]))
sys.argv=[os.path.join(HERE,'gen_docpage2.py'), HERE+'/throw/dp3.html']
exec(open(sys.argv[0]).read())
ptabs=lambda on:'<div class="ui-tabs" style="margin:0;padding:0 14px">'+''.join(f'<span class="ui-tab{" on" if k==on else ""}">{l}{f"<span class=ui-tab-count>{c}</span>" if c else ""}</span>' for k,l,c in [('docs','Documente',5),('types','Tipuri de documente',4)])+'</div>'
headA=('<div class="wh"><div><h1>Documente</h1><p>Documentele sportivilor, generate din înscrieri sau încărcate. Nu sunt publice.</p></div></div>')
WA1=('<div class="win" style="padding-bottom:110px">'+headA+ptabs('docs')+head2.replace('<div class="wh"><div><h1>Documente</h1><p>Toate documentele sportivilor: generate din înscrieri sau încărcate. Nu sunt publice.</p></div><span class="sp"></span>','<div class="wh" style="border-bottom:0;padding-bottom:0"><span class="sp"></span>')+tb2+table2()+'<div class="pgr">5 documente<span style="flex:1"></span><span class="pg on">1</span></div></div>')
WA2=('<div class="win">'+headA+ptabs('types')+'<div class="wh" style="border-bottom:0"><p style="margin:0">Tipurile noi apar singure la filtre, la formulare goale și în fișa sportivului.</p><span class="sp"></span><span class="btn pr">'+ic('plus')+'Tip nou</span></div>'+tt+'<div class="ft" style="justify-content:flex-start"><span class="hint">"Generat automat" = PDF din datele înscrierii, cere un șablon făcut de noi. "Încărcat" = admin încarcă PDF-ul; se poate adăuga oricând.</span></div></div>')
# B: drawer from button
drw=('<div class="dim"></div><div class="drw" style="width:560px"><div class="dh"><div style="flex:1"><h3>Tipuri de documente</h3><div class="hint">Tipurile noi apar singure la filtre și la formulare goale.</div></div><span class="btn sm pr">'+ic('plus')+'Tip nou</span><span style="margin-left:8px">'+ic('x')+'</span></div><div class="db" style="padding:0">'
 +''.join(f'<div style="display:grid;grid-template-columns:28px 1fr auto;gap:10px;align-items:center;padding:12px 18px;border-bottom:1px solid var(--ln)"><span class="dic" style="width:28px;height:28px">{ic("file")}</span><div><b>{a}</b><div class="hint">{b} · {c} · {e}</div></div><span class="lnk">Editează</span></div>' for a,b,c,d,e in TYPES)+'</div></div>')
WB=('<div class="win" style="padding-bottom:110px">'+head2.replace('<span class="btn">'+ic('dl')+'ZIP sezon</span>','<span class="btn">'+ic('dl')+'ZIP sezon</span><span class="btn">'+ic('gear')+'Tipuri</span>')+tb2+table2()+'<div class="pgr">5 documente<span style="flex:1"></span><span class="pg on">1</span></div></div>')
html=(css+ecss+tcss+ccss+mcss+'<style>'+PCSS+'</style>'+xc+qc+x3+oc+dcss+xc2+'<div class="A"><h2>Tipurile de documente, direct în Documente</h2><p class="note">Nu mai e în Setări site. Două variante. Date inventate.</p><div class="options wcol" style="flex-direction:column!important">'
 +O('A','tabs','Două taburi în pagina Documente: "Documente" și "Tipuri de documente" (recomandat)','<p class="cap2">Tab Documente</p>'+screen('documente',WA1)+'<p class="cap2" style="margin-top:14px">Tab Tipuri de documente</p>'+screen('documente',WA2),'Totul despre documente într-un singur loc; tipurile se văd ușor, dar nu încurcă lista.')
 +O('B','drawer','Buton "Tipuri" care deschide un panou lateral',screen('documente',WB,drw),'Lista rămâne singură pe pagină; tipurile se gestionează rar, deci stau ascunse.')+'</div></div>')
open(OUTDP3,'w').write(html)
